    if(pdf){objectUrl=URL.createObjectURL(blob);const frame=document.createElement('iframe');frame.className='preview-frame';frame.title='PDF preview';frame.src=objectUrl;body.append(frame);info.textContent='PDF preview · use the Download original button if your browser does not display PDFs.'}
