function fileAsDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read '+file.name));reader.readAsDataURL(file)})}
function documentPanel(k,id){const record=db[k].find(r=>r.id===id);if(!record)return;const current=record.attachments||[];document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="docs-title"><h2 id="docs-title">Attached documents</h2><p class="sub">${esc(record.title||record.machine||record.name||record.employee||record.location)}</p><div id="doc-items" class="attachment-list">${attachmentHTML(current)}</div>${k==='assets'?'<label class="checkrow" style="margin:10px 0"><input id="mark-manual" type="checkbox"> Mark new attachments as manufacturer operating manuals</label>':''}<label class="form-field full" style="margin-top:18px"><span>Add manuals, inspection certificates, photos or other supporting documents</span><input id="doc-file" class="field" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.txt"></label><p class="file-tip">15 MB per file; 200 MB combined attachments. Files are stored in this browser profile, not uploaded to a server. Export a backup to save a second copy.</p><div class="modal-actions"><button type="button" class="btn" id="cancel">Close</button><button type="button" class="btn primary" id="doc-add">Attach selected files</button></div></div></div>`;const root=document.getElementById('modal-root');root.querySelector('#cancel').onclick=closeModal;root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewAttachment(current[Number(b.dataset.preview)],k,id));root.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadAttachment(current[Number(b.dataset.download)]));root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this attachment?'))return;const previous=[...current];record.attachments=current.filter((_,i)=>i!==Number(b.dataset.remove));if(!save()){record.attachments=previous;return}render();documentPanel(k,id);toast('Document removed')});root.querySelector('#doc-add').onclick=async()=>{const files=[...root.querySelector('#doc-file').files];if(!files.length){alert('Select one or more documents first.');return}if(files.some(f=>!allowedExtensions.test(f.name)||f.size>MAX_FILE_BYTES||f.size===0)){alert('Supported formats: PDF, Word, Excel, JPG, PNG and TXT. Each file must be between 1 byte and 15 MB.');return}if(bytesUsed()+files.reduce((sum,f)=>sum+f.size,0)>MAX_TOTAL_BYTES){alert('Attachments would exceed the 200 MB total storage limit. Remove older attachments or keep large files separately.');return}try{const items=[];for(const f of files)items.push({name:f.name,size:f.size,type:f.type||'application/octet-stream',role:k==='assets'&&root.querySelector('#mark-manual')?.checked?'Operating Manual':'Supporting Document',data:await fileAsDataURL(f)});const old=record.attachments;record.attachments=[...current,...items];if(!save()){record.attachments=old;return}render();documentPanel(k,id);toast('Document(s) attached')}catch(err){alert('Attachment failed: '+err.message)}};root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function openForm(k,id){const record=id?db[k].find(r=>r.id===id):null;if(id&&!record)return;const form=config[k].fields.map(([f,label,type,required,options])=>{const val=record?.[f]??'';let control='';if(type==='select')control=`<select class="field" name="${f}" ${required?'required':''}>${options.map(s=>`<option value="${esc(s)}" ${s===val?'selected':''}>${esc(s)}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea class="field" name="${f}" ${required?'required':''}>${esc(val)}</textarea>`;else if(type==='checkbox')return `<label class="form-field full checkrow"><input type="checkbox" name="${f}" ${val?'checked':''}><span>${esc(label)}</span></label>`;else control=`<input class="field" type="${type}" name="${f}" value="${esc(val)}" ${required?'required':''} ${type==='number'?'min="0" max="30" step="0.01"':''}>`;return `<label class="form-field ${type==='textarea'?'full':''}"><span>${esc(label)}</span>${control}</label>`}).join('');document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${record?'Edit':'Add'} ${esc(config[k].short)}</h2><p class="sub">${record?'Update the details below.':'Complete the fields below to create a record.'}</p><form id="entry-form"><div class="form-grid">${form}</div>${k==='training'?'<div class="form-field full" style="margin-bottom:16px"><span>Attach training sheets or certificates</span><input class="field" id="training-files" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.txt"><p class="file-tip">Attach files here before saving (15 MB each; 200 MB total). Existing attachments will be retained. To remove old files, use the Files button in the register.</p></div>':'<p class="file-tip">To add or manage documents, save this record first, then choose the 📎 Files button in its register row.</p>'}${k==='ppe'?'<p class="notice">£30 is the maximum reimbursable amount per replacement. Inspection confirmation must be recorded before a claim can be approved or paid.</p>':''}<div class="modal-actions"><button class="btn" type="button" id="cancel">Cancel</button><button class="btn primary" type="submit">Save record</button></div></form></div></div>`;document.getElementById('cancel').onclick=closeModal;document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};const formEl=document.getElementById('entry-form');const first=formEl.querySelector('input:not([type=checkbox]),select,textarea');first?.focus();formEl.onsubmit=async e=>{e.preventDefault();const submitButton=formEl.querySelector('button[type="submit"]');if(submitButton)submitButton.disabled=true;try{const fd=new FormData(formEl);const r={...(record||{}),attachments:record?.attachments||[],signatures:record?.signatures||[],id:record?.id||('id_'+Date.now()+'_'+Math.random().toString(36).slice(2,8))};for(const [f,,type]of config[k].fields)r[f]=type==='checkbox'?formEl.elements[f].checked:type==='number'?Number(fd.get(f)):String(fd.get(f)??'').trim();if(k==='ppeStock'){const qty=Number(r.stock),min=r.minStock===''?null:Number(r.minStock);if(!/^\d+$/.test(r.stock)||!Number.isSafeInteger(qty)||qty<0||(min!==null&&(!/^\d+$/.test(r.minStock)||!Number.isSafeInteger(min)||min<0))){alert('PPE stock and minimum stock must be whole numbers of zero or more.');return}}if(k==='ppe'){if(!Number.isFinite(r.amount)||r.amount<0||r.amount>30){alert('The amount claimed must be between £0 and £30.');return}if(['Approved','Paid'].includes(r.claimStatus)&&!r.inspected){alert('Please confirm the previous boots were inspected and found unfit for purpose before approving or paying a claim.');return}}if(!config[k].fields.filter(f=>f[3]).every(([f])=>String(r[f]??'').trim().length>0)){alert('Please complete all required fields.');return}if(k==='training'){const files=[...(formEl.querySelector('#training-files')?.files||[])];if(files.some(f=>!allowedExtensions.test(f.name)||f.size<=0||f.size>MAX_FILE_BYTES)){alert('Only PDF, Word, Excel, JPG, PNG or TXT files between 1 byte and 15 MB are supported.');return}if(bytesUsed()+files.reduce((n,f)=>n+f.size,0)>MAX_TOTAL_BYTES){alert('Adding these files would exceed the 200 MB total attachment limit.');return}try{const items=[];for(const file of files)items.push({name:file.name,size:file.size,type:file.type||'application/octet-stream',role:'Training Evidence',data:await fileAsDataURL(file)});r.attachments=[...r.attachments,...items]}catch(err){alert('Unable to attach training sheet: '+err.message);return}}const previous=[...db[k]];if(record)db[k]=db[k].map(a=>a.id===record.id?r:a);else db[k].unshift(r);if(!save()){db[k]=previous;return}closeModal();render();toast(record?'Record updated':'Record added')}finally{if(submitButton&&submitButton.isConnected)submitButton.disabled=false}}}
function openAssetProfile(id){
  const r=db.assets.find(a=>a.id===id);if(!r)return;
  const manual=assetManual(r),docs=r.attachments||[];
  const fields=[['Asset ID',r.assetId],['Area / location',r.area],['Manufacturer',r.manufacturer],['Model',r.model],['Serial number',r.serialNumber],['Manual reference',r.manualReference],['Responsible person',r.person],['Next inspection',r.inspectionDate?dateFmt(r.inspectionDate):'Not recorded'],['Inspection priority',reviewPriority(r.inspectionDate)],['Equipment status',r.status]];
  const details=fields.map(([name,val])=>`<div class="asset-profile-field"><span>${esc(name)}</span><strong>${esc(val||'Not recorded')}</strong></div>`).join('');
  const attached=docs.map((a,i)=>`<div class="attachment-item"><span>📄 ${esc(a.name)} ${a.role==='Operating Manual'?'<span class="status good">Operating manual</span>':''}</span><button type="button" class="btn small" data-profile-file="${i}">Open</button></div>`).join('');
  const root=document.getElementById('modal-root');
  root.innerHTML=`<div class="modal-backdrop"><div class="modal preview-modal" role="dialog" aria-modal="true" aria-labelledby="asset-profile-title"><p class="eyebrow">Equipment profile</p><h2 id="asset-profile-title">${esc(r.name)}</h2><p class="sub">All available information for this asset. Unverified information must be confirmed on site.</p><div class="asset-profile-grid">${details}</div><h2 style="margin:22px 0 10px">Equipment notes</h2><p class="file-tip">${esc(r.notes||'No notes recorded.')}</p><h2 style="margin:22px 0 10px">Operating manual</h2><div class="callout">${manual?'An operating manual is attached.':'No operating manual attached. Confirm the correct manufacturer and model before adding one.'}</div><h2 style="margin:22px 0 10px">Supporting documents (${docs.length})</h2><div class="attachment-list">${attached||'<p class="muted">No documents attached yet.</p>'}</div><div class="modal-actions"><button type="button" class="btn" id="asset-profile-close">Close</button><button type="button" class="btn" id="asset-profile-docs">Manage documents</button><button type="button" class="btn primary" id="asset-profile-edit">Edit asset</button></div></div></div>`;
  root.querySelector('#asset-profile-close').onclick=closeModal;
  root.querySelector('#asset-profile-docs').onclick=()=>documentPanel('assets',id);
  root.querySelector('#asset-profile-edit').onclick=()=>openForm('assets',id);
  root.querySelectorAll('[data-profile-file]').forEach(b=>b.onclick=()=>previewAttachment(docs[Number(b.dataset.profileFile)],'assets',id));
  root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};
}
function openSignatures(k,id){
  if(!['risk','ssow'].includes(k))return;
  const rec=db[k].find(x=>x.id===id);if(!rec)return;
  const entries=rec.signatures||[];
  const root=document.getElementById('modal-root');
  root.innerHTML=`<div class="modal-backdrop"><div class="modal preview-modal" role="dialog" aria-modal="true" aria-labelledby="signature-heading"><h2 id="signature-heading">Sign-off records</h2><p class="sub">${esc(rec.title||rec.machine)} — acknowledgement of this specific document version. This does not replace practical training or formal approval.</p><div class="attachment-list">${entries.length?entries.map((s,i)=>`<div class="attachment-item"><div><strong>${esc(s.name)}</strong> · ${esc(s.role)} · ${esc(s.date)}<div class="muted">${s.signatureImage?'<img alt="Drawn signature" style="max-width:220px;max-height:70px;display:block" src="'+esc(s.signatureImage)+'">':'<span class="muted">Typed: '+esc(s.typedSignature||s.name)+'</span>'}</div></div><button class="btn small danger" type="button" data-remove-sign="${i}">Remove</button></div>`).join(''):'<p class="muted">No one has signed yet.</p>'}</div><form id="signature-form"><div class="form-grid"><label class="form-field"><span>Person signing</span><input class="field" name="name" required maxlength="120"></label><label class="form-field"><span>Role</span><input class="field" name="role" required maxlength="120"></label><label class="form-field"><span>Date</span><input class="field" type="date" name="date" required value="${new Date().toISOString().slice(0,10)}"></label><label class="form-field"><span>Document revision / reference</span><input class="field" name="revision" maxlength="120" value="${esc(rec.revision||rec.title||rec.machine)}"></label></div><p class="file-tip">Choose how to sign. You can type your name or draw using a mouse, finger or stylus.</p><label class="form-field"><span>Signature method</span><select class="field" id="signature-method"><option value="typed">Type my signature</option><option value="drawn">Draw my signature</option></select></label><label class="form-field" id="typed-signature-row"><span>Typed signature (full name)</span><input class="field" id="typed-signature" maxlength="120" placeholder="Type your full name" autocomplete="name"></label><div id="drawn-signature-row" hidden><canvas id="signature-pad" width="700" height="170" style="width:100%;height:170px;border:1px solid #cbd7c5;border-radius:10px;background:white;touch-action:none" aria-label="Draw your signature"></canvas><p><button class="btn small" type="button" id="clear-signature">Clear signature</button></p></div><label class="checkrow"><input type="checkbox" name="ack" required><span>I confirm I have read and understood the identified Risk Assessment or SSOW, and that this signature is my own.</span></label><div class="modal-actions"><button class="btn" type="button" id="close-signatures">Close</button><button class="btn primary" type="submit">Save signed acknowledgement</button></div></form></div></div>`;
  const canvas=root.querySelector('#signature-pad'),ctx=canvas.getContext('2d');ctx.strokeStyle='#1c2f25';ctx.lineWidth=2.5;ctx.lineCap='round';let active=false,drawn=false;const method=root.querySelector('#signature-method'),typed=root.querySelector('#typed-signature'),typedRow=root.querySelector('#typed-signature-row'),drawnRow=root.querySelector('#drawn-signature-row');method.onchange=()=>{typedRow.hidden=method.value!=='typed';drawnRow.hidden=method.value!=='drawn';typed.required=method.value==='typed'};method.onchange();
  function position(e){const b=canvas.getBoundingClientRect();return {x:(e.clientX-b.left)*canvas.width/b.width,y:(e.clientY-b.top)*canvas.height/b.height}}
  canvas.onpointerdown=e=>{active=true;canvas.setPointerCapture(e.pointerId);const p=position(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();drawn=true};
  canvas.onpointermove=e=>{if(!active)return;const p=position(e);ctx.lineTo(p.x,p.y);ctx.stroke();drawn=true};
  canvas.onpointerup=()=>active=false;canvas.onpointercancel=()=>active=false;
  root.querySelector('#clear-signature').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);drawn=false};
  root.querySelector('#close-signatures').onclick=closeModal;
  root.querySelectorAll('[data-remove-sign]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this acknowledgement?'))return;const old=rec.signatures;rec.signatures=entries.filter((_,i)=>i!==Number(b.dataset.removeSign));if(!save()){rec.signatures=old;return}openSignatures(k,id)});
  root.querySelector('#signature-form').onsubmit=e=>{e.preventDefault();if(method.value==='drawn'&&!drawn){alert('Please draw your signature before saving.');return}if(method.value==='typed'&&!typed.value.trim()){alert('Please type your signature before saving.');return}const f=new FormData(e.currentTarget);const sig={name:String(f.get('name')).trim(),role:String(f.get('role')).trim(),date:String(f.get('date')),revision:String(f.get('revision')||''),signedAt:new Date().toISOString(),signatureMethod:method.value,typedSignature:method.value==='typed'?typed.value.trim():'',signatureImage:method.value==='drawn'?canvas.toDataURL('image/png'):''};if(!sig.name||!sig.role||!sig.date)return;const old=rec.signatures;rec.signatures=[...entries,sig];if(!save()){rec.signatures=old;return}openSignatures(k,id);toast('Acknowledgement saved')};
  root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};
}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function printPermitPDF(id){
 const r=db.permits.find(x=>x.id===id);if(!r)return;
 const popup=window.open('','_blank');
 if(!popup){alert('Please allow pop-ups for this local dashboard to generate a permit PDF.');return}
 const clean=v=>esc(v||'—').replace(/\n/g,'<br>');
 const field=(label,value)=>'<div class="field"><span>'+label+'</span><strong>'+clean(value)+'</strong></div>';
 const type=permitTypeChecks[r.permitType]?r.permitType:'General / non-routine work';
 const checks=permitTypeChecks[type],results=r.permitChecks?.[type]||[];
 const safetyRows=checks.map((q,i)=>'<tr><td>'+esc(q)+'</td><td>'+ (results[i]?'Recorded ✓':'Not recorded')+'</td></tr>').join('');
 const css=`<style>@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#23372d;margin:0}header{border-bottom:4px solid #338457;padding-bottom:14px;margin-bottom:18px}.brand{font-size:14px;font-weight:bold;color:#2d8054;letter-spacing:1px}h1{font-size:25px;margin:8px 0 4px}h2{font-size:14px;color:#236342;border-bottom:1px solid #dbe7dd;padding-bottom:6px;margin:20px 0 10px}.warning{border:2px solid #bc6228;padding:10px 13px;background:#fff5e8;font-weight:bold;color:#8b4116;margin:15px 0;line-height:1.5}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.field{padding:8px;border:1px solid #dce6df;min-height:46px;break-inside:avoid}.field span{display:block;font-size:10px;color:#607469;margin-bottom:5px}.field strong{font-size:12px;font-weight:600;overflow-wrap:anywhere}.wide{grid-column:1/-1}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #dce6df;padding:8px;text-align:left}th{background:#edf5ef}.sign{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.sign>div{border:1px solid #8fa797;min-height:88px;padding:8px}small{color:#627567}footer{font-size:10px;color:#64756b;border-top:1px solid #d9e6dd;margin-top:24px;padding-top:8px}.screen-toolbar{padding:12px;background:#eaf4ec;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center}.screen-toolbar button{padding:9px 16px;color:white;background:#267d53;border:0;border-radius:5px;cursor:pointer}@media print{.screen-toolbar{display:none}h2,header{break-after:avoid}table,.sign{break-inside:avoid}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style>`;
 const html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Permit '+esc(r.reference||r.title)+'</title>'+css+'</head><body><div class="screen-toolbar"><span>Print / Save as PDF in Microsoft Edge</span><button onclick="window.print()">Print / Save as PDF</button></div><header><div class="brand">ONBOARD CORRUGATED · HEALTH & SAFETY</div><h1>PERMIT TO WORK</h1><small>Permit planning record · Generated '+esc(new Date().toLocaleString('en-GB'))+'</small></header><div class="warning">NOT A VALID WORK AUTHORISATION. No work may start based solely on this PDF. The site permit procedure, competent-person checks, signatures and issue of an approved permit are required.</div><h2>Work details</h2><div class="grid">'+field('Permit reference',r.reference)+field('Permit category',r.permitType)+field('Activity',r.title)+field('Location / machine',r.area)+field('Contractor / personnel',r.contractor)+field('Proposed site authoriser',r.person)+field('Planned start', (r.startDate||'')+' '+(r.startTime||''))+field('Planned finish',(r.endDate||'')+' '+(r.endTime||''))+field('Risk assessment / method statement',r.riskRef)+field('Isolation / lockout reference',r.isolationRef)+field('Record status (not approval)',r.status)+'</div><h2>Hazards and controls</h2><div class="grid">'+field('Task hazards and control measures',r.controls)+field('Emergency arrangements',r.emergency)+field('Plant handback / close-out notes',r.handover)+'</div><h2>Pre-work safety checks — recorded only</h2><table><thead><tr><th>Control check</th><th>Recorded status</th></tr></thead><tbody>'+safetyRows+'</tbody></table><div class="grid" style="margin-top:12px">'+field('Outstanding controls / evidence',r.permitCheckNotes)+'</div><h2>Site authorisation & handback (complete under approved procedure)</h2><div class="sign"><div>Issuer / competent authoriser<br><br>Name: _______________________<br><br>Signature: ____________________<br><br>Date / time: _________________</div><div>Receiver / person in charge<br><br>Name: _______________________<br><br>Signature: ____________________<br><br>Date / time: _________________</div><div>Isolation verified by<br><br>Name: _______________________<br><br>Signature: ____________________<br><br>Date / time: _________________</div><div>Work complete / plant returned safe<br><br>Name: _______________________<br><br>Signature: ____________________<br><br>Date / time: _________________</div></div><footer>Onboard Corrugated · Browser dashboard export · Record reference: '+esc(r.reference||r.id)+' · Retain signed and approved permit as company-controlled record.</footer></body></html>';
 popup.document.open();popup.document.write(html);popup.document.close();popup.focus();
}
function handleAction(action,k,id){if(action==='permitpdf')return printPermitPDF(id);if(action==='permitpdf')return printPermitPDF(id);if(action==='permitcheck')return openPermitChecks(id);if(action==='auditcheck')return openAuditChecklist(id);if(action==='ppe-tab')return go(k);if(action==='signatures')return openSignatures(k,id);if(action==='profile')return openAssetProfile(id);if(action==='seedassets'){const keys=new Set(db.assets.map(a=>a.name.trim().toLowerCase()));const extra=suggestedAssets.filter(a=>!keys.has(a.name.toLowerCase())).map(a=>({...a,status:'Unverified',attachments:[]}));if(!extra.length){toast('All suggested machine groups are already listed');return}if(!confirm('Add '+extra.length+' suggested equipment groups? Verify real equipment details before use.'))return;const old=[...db.assets];db.assets.push(...extra);if(!save()){db.assets=old;return}render();toast(extra.length+' example assets added');return}if(action==='openmanual'){const r=db.assets.find(a=>a.id===id);const manual=r&&assetManual(r);if(manual)previewAttachment(manual,'assets',id);return}if(action==='add'||action==='edit')return openForm(k,action==='edit'?id:null);if(action==='docs')return documentPanel(k,id);if(action==='quickopen'){const r=db[k].find(x=>x.id===id);if(r?.attachments?.length)return previewAttachment(r.attachments[r.attachments.length-1],k,id);return}if(action==='delete'){if(!confirm('Delete this record? This cannot be undone unless you have a backup.'))return;const old=[...db[k]];db[k]=db[k].filter(r=>r.id!==id);if(!save()){db[k]=old;return}render();toast('Record deleted');return}if(action==='export')return exportBackup();if(action==='import')return importBackup();if(action==='reset'){if(!confirm('Replace ALL saved records with the fictional example data? Export a backup first if needed.'))return;const old=db;db=examples();if(!save()){db=old;return}render();toast('Example data restored')}}
async function exportBackup(){if(window.browserSavePending)await window.browserSavePending();const blob=new Blob([JSON.stringify({app:'Onboard Corrugated H&S Dashboard',version:2,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'});const a=document.createElement('a');const u=URL.createObjectURL(blob);a.href=u;a.download=`onboard-hs-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Backup exported')}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>300_000_000)throw Error('File is too large (maximum 300 MB).');const parsed=JSON.parse(await file.text());if(parsed?.app!=='Onboard Corrugated H&S Dashboard'||![1,2].includes(parsed.version))throw Error('Not a compatible dashboard backup.');const data=parsed.data;if(data&&data.assets===undefined)data.assets=[];if(data&&data.ppeStock===undefined)data.ppeStock=[];if(data&&data.training===undefined)data.training=[];for(const key of extraModuleKeys)if(data&&data[key]===undefined)data[key]=[];if(!data||!Object.keys(config).every(k=>Array.isArray(data[k])&&data[k].length<=10000&&data[k].every(r=>r&&typeof r.id==='string'&&config[k].fields.every(([f,,type])=>type==='checkbox'?typeof r[f]==='boolean':type==='number'?typeof r[f]==='number'&&r[f]>=0&&r[f]<=30:(!f||typeof r[f]==='string'||(r[f]===undefined&&!config[k].fields.find(x=>x[0]===f)[3]))))))throw Error('Backup contains invalid records.');if(!Object.values(data).flat().every(r=>r.attachments===undefined||(Array.isArray(r.attachments)&&r.attachments.every(a=>a&&typeof a.name==='string'&&a.name.length<250&&allowedExtensions.test(a.name)&&typeof a.size==='number'&&a.size>0&&a.size<=MAX_FILE_BYTES&&typeof a.data==='string'&&/^data:[^,]*;base64,/.test(a.data)&&a.data.length<22000000))))throw Error('Backup contains invalid attachments.');if(bytesUsed(data)>MAX_TOTAL_BYTES)throw Error('Backup exceeds the 200 MB attachment limit.');if(!confirm('Importing will REPLACE every current record. Continue?'))return;const old=db;db=data;if(!save()){db=old;return}if(window.browserSavePending)await window.browserSavePending();render();toast('Backup imported')}catch(err){alert('Import failed: '+err.message)}};input.click()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});render();
